(() => {
'use strict';
const POSTER="data:image/png;base64,";

const PORTS=Array.from({length:8},(_,i)=>{
  const id=i+1;
  if(id===8)return {id,endpoint:'SW2',vlans:[10,20],active:true,trunk:true};
  const endpoint={1:'PC A',2:'PC B',3:'PC C'}[id];
  return {id,endpoint:endpoint||'ว่าง',vlans:endpoint?[id===3?20:10]:[],active:!!endpoint,trunk:false};
});
const HOSTS={
  A:{port:1,mac:'02:00:00:00:00:AA'},
  B:{port:2,mac:'02:00:00:00:00:BB'}
};
function transmit(table,from,to){
  const src=HOSTS[from],dst=HOSTS[to],vlan=10;
  const learned={...table,[vlan+'/'+src.mac]:src.port};
  const port=learned[vlan+'/'+dst.mac];
  const eligible=PORTS.filter(item=>item.active&&item.id!==src.port&&item.vlans.includes(vlan));
  const outputs=eligible.filter(item=>port===undefined||item.id===port).map(item=>item.id);
  return {table:learned,outputs,input:src.port,known:port!==undefined,from,to};
}
function projectedPort(id,pose,width,height) {
  const yaw=pose.yaw,pitch=pose.pitch,z=1.58,x=(id-4.5)*.94;
  const y=.02+(.97-.76)*pose.split;
  const px=Math.cos(yaw)*x+Math.sin(yaw)*z;
  const pz=-Math.sin(yaw)*x+Math.cos(yaw)*z;
  const py=Math.cos(pitch)*y-Math.sin(pitch)*pz;
  const depth=Math.sin(pitch)*y+Math.cos(pitch)*pz;
  const aspect=width/height;
  const distance=(Math.max(2.03,4.73/aspect)*3.52+2.05)/pose.zoom;
  return [width*(.5+.5*px*3.52/(aspect*(distance-depth))),height*(.5-.5*py*3.52/(distance-depth))];
}


function makeSwitchGeometry() {
  const vertices=[];
  const metal=[.53,.55,.59], edge=[.30,.32,.35], bezel=[.075,.082,.091];
  const pcb=[.04,.22,.15], black=[.019,.023,.028], gold=[.76,.56,.24];
  const clamp=(value,min,max)=>Math.min(max,Math.max(min,value));
  function box(center,size,color,polish=0,layer=0,radius=0,lamp=0) {
    const half=size.map(n=>n/2);
    const r=Math.min(radius,...half.map(h=>h*.9));
    function samples(h) {
      if(!r)return [-h,h];
      return [-h,-h+r*.24,-h+r*.57,-h+r,h-r,h-r*.57,h-r*.24,h];
    }
    for(let axis=0;axis<3;axis++) for(const sign of [-1,1]) {
      const u=(axis+1)%3,v=(axis+2)%3;
      const us=samples(half[u]),vs=samples(half[v]);
      function vertex(a,b) {
        const p=[0,0,0],n=[0,0,0];
        p[axis]=sign*half[axis];p[u]=a;p[v]=b;
        if(r) {
          const q=p.map((val,i)=>clamp(val,-half[i]+r,half[i]-r));
          const len=Math.hypot(...p.map((val,i)=>val-q[i]));
          for(let i=0;i<3;i++){n[i]=(p[i]-q[i])/len;p[i]=q[i]+n[i]*r;}
        } else n[axis]=sign;
        vertices.push(...p.map((val,i)=>val+center[i]),...n,...color,polish,layer,lamp);
      }
      for(let i=1;i<us.length;i++)for(let j=1;j<vs.length;j++){
        const a=us[i-1],b=us[i],c=vs[j-1],d=vs[j];
        vertex(a,c);vertex(b,c);vertex(b,d);vertex(a,c);vertex(b,d);vertex(a,d);
      }
    }
  }
  box([0,-.53,0],[8.2,.17,3.20],metal,.86,0,.07);
  box([0,.52,0],[8.22,.18,3.22],metal,.96,1,.08);
  for(const side of [-1,1]){
    box([side*4.04,0,0],[.13,1.05,3.16],metal,.84,1,.045);
    for(let i=0;i<14;i++)box([side*4.11,.02,-1.13+i*.12],[.012,.27,.048],black,.12,1);
    for(const z of [-1.04,1.04])box([side*3.36,-.65,z],[.60,.13,.43],black,.12,0,.035);
  }
  box([0,-.04,-1.53],[8.02,.97,.10],edge,.7,0,.03);
  box([2.9,-.09,-1.61],[.57,.46,.09],black,.2,0,.025);
  box([2.9,-.09,-1.67],[.23,.20,.035],edge,.85,0);
  box([0,-.33,0],[7.82,.10,2.85],pcb,.2,2,.035);
  box([-.42,-.18,-.30],[1.16,.21,.91],black,.25,2,.04);
  for(let i=0;i<10;i++){
    box([-.92+i*.112,-.24,.21],[.048,.047,.18],metal,.85,2);
    box([-.92+i*.112,-.24,-.81],[.048,.047,.18],metal,.85,2);
    box([1.27+i*.095,-.12,-.38],[.035,.24,.74],metal,.88,2);
  }
  box([1.7,-.24,-.38],[1.07,.07,.85],edge,.6,2);
  for(let i=0;i<18;i++){
    const x=-3.5+(i%9)*.82,z=-1.08+Math.floor(i/9)*.42;
    box([x,-.226,z],[.22,.093,.13],i%3===0?gold:bezel,.33,2);
  }
  box([0,-.385,1.55],[7.96,.29,.11],bezel,.4,0,.025);
  box([0,.377,1.55],[7.96,.17,.11],bezel,.4,0,.02);
  const digits=['','bc','abdeg','abcdg','bcfg','acdfg','acdefg','abc','abcdefg'];
  const segments={a:[0,.06,.065,.011],b:[.034,.029,.011,.052],c:[.034,-.029,.011,.052],d:[0,-.06,.065,.011],e:[-.034,-.029,.011,.052],f:[-.034,.029,.011,.052],g:[0,0,.065,.01]};
  for(let port=1;port<=8;port++) {
    const x=(port-4.5)*.94;
    box([x,.024,1.19],[.86,.63,.62],bezel,.54,3,.035);
    box([x,.012,1.512],[.755,.47,.019],black,.04,3);
    for(const side of [-1,1]) {
      box([x+side*.405,.028,1.55],[.052,.6,.07],edge,.76,3);
      box([x,.028+side*.282,1.55],[.85,.045,.07],metal,.72,3);
    }
    box([x,.205,1.534],[.29,.091,.032],black,.05,3);
    for(let pin=0;pin<8;pin++)box([x-.268+pin*.076,-.133,1.54],[.027,.088,.022],gold,.82,3);
    box([x+.29,.245,1.591],[.105,.046,.021],[.16,.83,.48],.15,3,0,port);
    for(const key of digits[port]){
      const [dx,dy,w,h]=segments[key];box([x+dx,-.38+dy,1.612],[w,h,.005],[.75,.77,.79],.2);
    }
    box([x,-.271,.50],[.028,.01,.60],gold,.3,2);
    box([x*.5,-.272,.2-.035*port],[Math.max(.07,Math.abs(x)),.01,.022],gold,.26,2);
  }
  return new Float32Array(vertices);
}
function openSwitchRenderer(canvas) {
  const gl=canvas.getContext('webgl',{alpha:true,antialias:true,premultipliedAlpha:false,powerPreference:'low-power'});
  if(!gl)throw Error('WebGL unavailable');
  const vertexSource=`
    attribute vec3 aPosition,aNormal,aColor;
    attribute float aPolish,aLayer,aLamp;
    uniform float uYaw,uPitch,uSplit,uZoom,uAspect;
    varying mediump vec3 vNormal,vColor,vWorld,vLocal;
    varying mediump float vPolish,vLamp;
    void main(){
      vec3 p=aPosition;
      float offset=aLayer<0.5?0.0:(aLayer<1.5?1.95:(aLayer<2.5?0.63:0.97));
      p.y+=(offset-.76)*uSplit;
      float cy=cos(uYaw),sy=sin(uYaw),cx=cos(uPitch),sx=sin(uPitch);
      mat3 ry=mat3(cy,0.,-sy,0.,1.,0.,sy,0.,cy);
      mat3 rx=mat3(1.,0.,0.,0.,cx,sx,0.,-sx,cx);
      mat3 rotation=rx*ry;
      vec3 wp=rotation*p;
      float distance=(max(2.03,4.73/uAspect)*3.52+2.05)/uZoom;
      vec3 eye=wp-vec3(0.,0.,distance);
      gl_Position=vec4(eye.x*3.52/uAspect,eye.y*3.52,-1.002*eye.z-.2002,-eye.z);
      vNormal=rotation*aNormal; vWorld=eye; vLocal=aPosition;
      vColor=aColor; vPolish=aPolish; vLamp=aLamp;
    }`;
  const fragmentSource=`
    precision mediump float;
    varying mediump vec3 vNormal,vColor,vWorld,vLocal;
    varying mediump float vPolish,vLamp;
    uniform vec3 uLit;
    uniform float uTime;
    void main(){
      vec3 n=normalize(vNormal),view=normalize(-vWorld),r=reflect(-view,n);
      vec3 key=normalize(vec3(-.34,.82,.57)),fill=normalize(vec3(.75,.27,.6));
      float diffuse=.37+.52*max(dot(n,key),0.)+.23*max(dot(n,fill),0.);
      float rim=pow(1.-max(dot(n,view),0.),3.);
      float band=r.x+.55*r.y-.22, horizon=r.y-.8;
      float studio=exp(-18.*band*band)*.46+exp(-40.*horizon*horizon)*.32;
      float brush=.012*sin(vLocal.z*390.+sin(vLocal.x*7.3)*2.);
      vec3 c=vColor*diffuse+vPolish*(studio*(.25+vColor*.55)+rim*.15+brush);
      if(vLamp>.5){
        float hot=min(abs(vLamp-uLit.x),min(abs(vLamp-uLit.y),abs(vLamp-uLit.z)));
        bool used=vLamp<3.5||vLamp>7.5;
        c=used?(hot<.3?vec3(.40,.98,.68)*(.88+.12*sin(uTime*5.)):vec3(.08,.42,.22)):vec3(.06,.12,.10);
      }
      gl_FragColor=vec4(c,1.);
    }`;
  const shaders=[];
  let program=null,buffer=null;
  function dispose(){
    if(buffer)gl.deleteBuffer(buffer);
    if(program)gl.deleteProgram(program);
    shaders.forEach(shader=>gl.deleteShader(shader));
  }
  function shader(type,source){
    const item=gl.createShader(type);shaders.push(item);gl.shaderSource(item,source);gl.compileShader(item);
    if(!gl.getShaderParameter(item,gl.COMPILE_STATUS))throw Error('Shader unavailable');
    return item;
  }
  try{
    program=gl.createProgram();
    gl.attachShader(program,shader(gl.VERTEX_SHADER,vertexSource));
    gl.attachShader(program,shader(gl.FRAGMENT_SHADER,fragmentSource));
    gl.linkProgram(program);
    if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('Program unavailable');
    gl.useProgram(program);
    const data=makeSwitchGeometry();
    buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);
    for(const [name,size,offset] of [['aPosition',3,0],['aNormal',3,3],['aColor',3,6],['aPolish',1,9],['aLayer',1,10],['aLamp',1,11]]){
      const location=gl.getAttribLocation(program,name);
      gl.enableVertexAttribArray(location);gl.vertexAttribPointer(location,size,gl.FLOAT,false,48,offset*4);
    }
    const uniforms={};
    for(const name of ['Yaw','Pitch','Split','Zoom','Aspect','Lit','Time'])uniforms[name]=gl.getUniformLocation(program,'u'+name);
    gl.enable(gl.DEPTH_TEST);gl.depthFunc(gl.LEQUAL);gl.clearColor(0,0,0,0);
    return {
      draw(state,time){
        const bounds=canvas.getBoundingClientRect();
        const ratio=Math.min(window.devicePixelRatio||1,1.75);
        const w=Math.max(1,Math.round(bounds.width*ratio)),h=Math.max(1,Math.round(bounds.height*ratio));
        if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}
        gl.viewport(0,0,w,h);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);
        gl.uniform1f(uniforms.Yaw,state.yaw);gl.uniform1f(uniforms.Pitch,state.pitch);gl.uniform1f(uniforms.Split,state.split);
        gl.uniform1f(uniforms.Zoom,state.zoom);gl.uniform1f(uniforms.Aspect,w/h);gl.uniform1f(uniforms.Time,time%1000);
        gl.uniform3f(uniforms.Lit,state.lights[0]||0,state.lights[1]||0,state.lights[2]||0);
        gl.drawArrays(gl.TRIANGLES,0,data.length/12);
      },dispose(){dispose();gl.getExtension("WEBGL_lose_context")?.loseContext();}
    };
  }catch(error){dispose();throw error;}
}


let current=null;
function install({main,hero,layout}) {
  if(!main||!hero||!layout||main.querySelector('.ns-showcase'))return;
  current?.();
  const life=new AbortController();
  const bind=(el,event,fn,extra={})=>el.addEventListener(event,fn,{...extra,signal:life.signal});
  const quiet=()=>document.documentElement.dataset.motion==='off'||matchMedia('(prefers-reduced-motion: reduce)').matches;
  const limit=(number,min,max)=>Math.max(min,Math.min(max,number));
  const scene=document.createElement('section');
  scene.className='ns-showcase';scene.setAttribute('aria-label','สำรวจ Ethernet Switch');
  scene.innerHTML=`<div class="ns-showcase-inner"><div class="ns-product-copy">
    <p class="ns-course">Network Final Lab · 01076040</p>
    <h1><span>Ethernet</span><span>Switch</span></h1>
    <p class="ns-lead">หมุนสวิตช์ สำรวจพอร์ต แล้วตามเฟรมจากต้นทางไปถึงปลายทาง</p>
    <div class="ns-action-slot"></div><button type="button" class="ns-jump">ทดลองส่งเฟรม ↓</button>
  </div><div class="ns-viewer" data-live="false">
    <div class="ns-stage"><img class="ns-poster" alt="สวิตช์เครือข่ายตัวถังโลหะ มีพอร์ต Ethernet 8 ช่อง">
      <canvas class="ns-canvas" tabindex="0" aria-label="โมเดลสวิตช์ 3D ใช้ปุ่มลูกศรเพื่อหมุน บวกหรือลบเพื่อซูม และ Home เพื่อคืนมุมมอง" aria-describedby="ns-help"></canvas>
      <div class="ns-cutaway" hidden role="img" aria-label="ชั้นส่วนประกอบ เรียงจากฝาครอบ ชิปและพอร์ต แผงวงจร และฐานตัวถัง"><div>ฝาครอบโลหะ</div><div>ชิปสวิตช์และพอร์ต Ethernet</div><div>แผงวงจร PCB</div><div>ฐานตัวถัง</div></div>
      <p class="ns-stage-hint" id="ns-help">ลากเพื่อหมุน 360° · เลือกพอร์ตเพื่อสำรวจ</p>
    </div><div class="ns-bar"><div class="ns-modes" role="group" aria-label="มุมมองสวิตช์">
      <button type="button" data-mode="body" aria-pressed="true">ตัวเครื่อง</button>
      <button type="button" data-mode="inside" aria-pressed="false">แยกชิ้นส่วน</button>
      <button type="button" data-mode="ports" aria-pressed="false">พอร์ต</button>
    </div><div class="ns-camera" role="group" aria-label="ควบคุมโมเดล">
      <button type="button" data-camera="auto" aria-pressed="false">หมุน 3D</button>
      <button type="button" data-camera="out" aria-label="ซูมออก">−</button>
      <output aria-label="ขนาดโมเดล">100%</output><button type="button" data-camera="in" aria-label="ซูมเข้า">+</button>
      <button type="button" data-camera="reset" aria-label="คืนมุมมองเริ่มต้น">รีเซ็ต</button>
      <button type="button" data-camera="full" aria-label="ดูโมเดลเต็มจอ">เต็มจอ</button>
    </div></div><div class="ns-inspect"><p class="ns-part-text" aria-live="polite"></p>
      <div class="ns-ports" role="group" aria-label="เลือกพอร์ต" hidden></div>
      <span class="ns-port-readout" aria-live="polite" hidden></span></div>
  </div></div>`;
  const actions=hero.querySelector('.actions');
  if(actions)scene.querySelector('.ns-action-slot').append(actions);
  const mascot=hero.querySelector('.quest-mascot img');
  const mission=layout.querySelector('.quest-mission');
  if(mascot&&mission){mascot.className='ns-bit';mascot.width=54;mascot.height=54;mission.prepend(mascot);}
  hero.replaceWith(scene);main.prepend(scene);
  document.body.classList.add('ns-home');
  const viewer=scene.querySelector('.ns-viewer'),canvas=scene.querySelector('canvas');
  scene.querySelector('.ns-poster').src=POSTER;
  const help=scene.querySelector('.ns-stage-hint'),partText=scene.querySelector('.ns-part-text');
  const portPicker=scene.querySelector('.ns-ports'),portInfo=scene.querySelector('.ns-port-readout');
  const zoomReadout=scene.querySelector('output'),camera=scene.querySelector('.ns-camera');
  const control=key=>camera.querySelector('[data-camera="'+key+'"]');
  let renderer=null,failed=false,closed=false,visible=true,spinning=false,mode='body',selectedPort=1;
  let timer=0,raf=0,last=0,drag=null,seq=0,mac={},lastFrame=null,playing=false;
  const pose={yaw:-.20,pitch:.31,split:0,zoom:1,lights:[1]};
  const target={yaw:pose.yaw,pitch:pose.pitch,split:0,zoom:1};
  function schedule(){
    if(!closed&&visible&&!document.hidden&&renderer&&!raf)raf=requestAnimationFrame(draw);
  }
  function draw(time) {
    raf=0;
    if(closed||!visible||document.hidden||!renderer)return;
    const delta=last?Math.min(48,time-last):16;last=time;
    if(spinning&&!quiet())target.yaw+=delta*.00022;
    const blend=quiet()?1:1-Math.exp(-delta/80);
    let moving=false;
    for(const name of ['yaw','pitch','split','zoom']){
      const diff=target[name]-pose[name];
      if(Math.abs(diff)>.0006){pose[name]+=blend*diff;moving=true;}else pose[name]=target[name];
    }
    renderer.draw(pose,quiet()?0:time/1000);
    if(moving||(spinning&&!quiet()))schedule();
  }
  function stopSpin(){spinning=false;control('auto').setAttribute('aria-pressed','false');control('auto').textContent='หมุน 3D';}
  function use3D(){
    if(failed||closed)return false;
    if(!renderer){
      try { renderer=openSwitchRenderer(canvas); }
      catch { failed=true;staticView();return false; }
    }
    viewer.dataset.live='true';schedule();return true;
  }
  function staticView(){
    viewer.dataset.live='false';stopSpin();
    viewer.querySelector('.ns-cutaway').hidden=mode!=='inside';
    help.textContent='โหมดภาพนิ่ง · เลือกพอร์ตและทดลองส่งเฟรมได้ด้านล่าง';
    for(const key of ['auto','out','in','reset'])control(key).disabled=true;
  }
  function zoom(amount){
    if(!use3D())return;
    target.zoom=limit(Math.round((target.zoom+amount)*100)/100,.75,1.45);
    zoomReadout.value=Math.round(target.zoom*100)+'%';
    control('in').disabled=target.zoom>=1.45;control('out').disabled=target.zoom<=.75;schedule();
  }
  function reset(){
    stopSpin();
    Object.assign(target,{yaw:-.20,pitch:.31,split:0,zoom:1});
    zoomReadout.value='100%';control('in').disabled=false;control('out').disabled=false;
    selectMode('body',false);viewer.dataset.live='false';
    help.textContent='ลากเพื่อหมุน 360° · เลือกพอร์ตเพื่อสำรวจ';
  }
  function selectPort(id){
    selectedPort=id;const port=PORTS[id-1];
    for(const b of portPicker.children)b.setAttribute('aria-pressed',String(Number(b.dataset.port)===id));
    portInfo.textContent=port.active
      ?(port.trunk?'P8 → SW2 · Trunk 802.1Q · อนุญาต VLAN 10 และ 20 (tagged)':'P'+id+' → '+port.endpoint+' · Access VLAN '+port.vlans[0]+' · Link up')
      :'P'+id+' · ไม่มีอุปกรณ์เชื่อมต่อ · Link down';
    pose.lights=[id];schedule();
  }
  for(const port of PORTS){
    const b=document.createElement('button');b.type='button';b.dataset.port=String(port.id);
    b.textContent='P'+port.id;b.setAttribute('aria-label','พอร์ต '+port.id+' '+port.endpoint);
    portPicker.append(b);bind(b,'click',()=>selectPort(port.id));
  }
  function selectMode(next,activate=true,keepAngle=false){
    mode=next;const inside=next==='inside',ports=next==='ports';
    if(activate)use3D();
    if(!keepAngle)Object.assign(target,inside?{yaw:-.38,pitch:.58}:ports?{yaw:-.04,pitch:.14}:{yaw:-.20,pitch:.31});
    target.split=inside?1:0;
    for(const b of scene.querySelectorAll('[data-mode]'))b.setAttribute('aria-pressed',String(b.dataset.mode===next));
    portPicker.hidden=!ports;portInfo.hidden=!ports;
    viewer.querySelector('.ns-cutaway').hidden=!(failed&&inside);
    if(ports){partText.textContent='เลือกช่องด้านล่าง หรือแตะช่องบนโมเดลขณะหันด้านหน้าเข้าหาคุณ';selectPort(selectedPort);}
    else if(inside)partText.innerHTML='<strong>ภายในสวิตช์</strong> · ฝาครอบยกขึ้นจากแผงวงจรสีเขียว ชิปสวิตช์ใช้ข้อมูล MAC และ VLAN เพื่อเลือกพอร์ตส่งเฟรม';
    else partText.innerHTML='<strong>โมเดลจำลอง 8 พอร์ต</strong> · P1 และ P2 ต่อเครื่องใน VLAN 10, P3 อยู่ VLAN 20 และ P8 เป็น Trunk ไป SW2';
    schedule();
  }
  for(const b of scene.querySelectorAll('[data-mode]'))bind(b,'click',()=>{stopSpin();selectMode(b.dataset.mode);});
  bind(control('out'),'click',()=>zoom(-.1));bind(control('in'),'click',()=>zoom(.1));bind(control('reset'),'click',reset);
  const fullButton=control('full');
  fullButton.hidden=!document.fullscreenEnabled||!viewer.requestFullscreen;
  bind(fullButton,'click',async()=>{
    try{
      if(document.fullscreenElement===viewer)await document.exitFullscreen();
      else await viewer.requestFullscreen();
    }catch{help.textContent='เบราว์เซอร์เปิดเต็มจอไม่ได้ · ยังหมุนและซูมตรงนี้ได้';}
  });
  bind(document,'fullscreenchange',()=>{
    fullButton.textContent=document.fullscreenElement===viewer?'ย่อจอ':'เต็มจอ';
    schedule();
  });
  bind(control('auto'),'click',()=>{
    if(!use3D())return;
    if(quiet()){stopSpin();target.yaw+=Math.PI/6;schedule();return;}
    spinning=!spinning;control('auto').setAttribute('aria-pressed',String(spinning));
    control('auto').textContent=spinning?'หยุดหมุน':'หมุน 3D';schedule();
  });
  bind(canvas,'pointerdown',e=>{
    if(e.button!==0||!use3D())return;
    stopSpin();drag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};
    canvas.setPointerCapture?.(e.pointerId);
  });
  bind(canvas,'pointermove',e=>{
    if(!drag||drag.id!==e.pointerId)return;
    const dx=e.clientX-drag.x,dy=e.clientY-drag.y;
    if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>5)drag.moved=true;
    target.yaw+=dx*.009;target.pitch=limit(target.pitch+dy*.007,-1.06,1.17);
    drag.x=e.clientX;drag.y=e.clientY;schedule();
  });
  bind(canvas,'pointerup',e=>{
    if(!drag||drag.id!==e.pointerId)return;
    const tapped=!drag.moved;drag=null;
    if(!tapped||Math.cos(pose.yaw)*Math.cos(pose.pitch)<.35)return;
    const b=canvas.getBoundingClientRect(),x=e.clientX-b.left,y=e.clientY-b.top;
    const nearest=PORTS.map(p=>{const xy=projectedPort(p.id,pose,b.width,b.height);return [p.id,Math.hypot(x-xy[0],y-xy[1])];}).sort((a,b)=>a[1]-b[1])[0];
    if(nearest[1]<Math.max(16,b.width*.045)){selectMode('ports',false,true);selectPort(nearest[0]);}
  });
  bind(canvas,'pointercancel',()=>{drag=null;});bind(canvas,'lostpointercapture',()=>{drag=null;});
  bind(canvas,'keydown',e=>{
    if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','Home'].includes(e.key))return;
    e.preventDefault();if(!use3D())return;stopSpin();
    if(e.key==='Home')reset();
    else if(e.key==='+'||e.key==='=')zoom(.1);
    else if(e.key==='-')zoom(-.1);
    else {if(e.key==='ArrowLeft')target.yaw-=.16;if(e.key==='ArrowRight')target.yaw+=.16;
      if(e.key==='ArrowUp')target.pitch=limit(target.pitch+.12,-1.06,1.17);
      if(e.key==='ArrowDown')target.pitch=limit(target.pitch-.12,-1.06,1.17);schedule();}
  });
  bind(canvas,'webglcontextlost',e=>{e.preventDefault();failed=true;renderer=null;staticView();});
  bind(canvas,'webglcontextrestored',()=>{failed=false;for(const key of ['auto','in','out','reset'])control(key).disabled=false;reset();});
  selectMode('body',false);
  const lab=document.createElement('section');lab.className='ns-lab';lab.id='network-frame-lab';lab.setAttribute('aria-labelledby','ns-lab-title');
  lab.innerHTML=`<div class="ns-lab-inner"><div class="ns-experiment"><h2 id="ns-lab-title">ตามรอย Ethernet Frame</h2>
    <p>PC A และ B อยู่ VLAN 10 ลองส่งเฟรมสามครั้ง แล้วดูว่าสวิตช์เลือกพอร์ตใด</p>
    <div class="ns-map"></div><div aria-live="polite"><span class="ns-stage-count"></span><div class="ns-lab-status"></div></div>
    <div class="ns-playback"><button type="button" class="primary" data-lab="step">ส่ง A → B</button>
    <button type="button" data-lab="play" aria-pressed="false">เล่นอัตโนมัติ</button><button type="button" data-lab="reset">เริ่มใหม่</button></div></div>
    <div class="ns-table-panel"><h3>MAC Address Table</h3><p>SW1 เรียนรู้ MAC ต้นทางจากพอร์ตขาเข้า</p>
    <table class="ns-lab-table"><thead><tr><th scope="col">MAC Address</th><th scope="col">VLAN</th><th scope="col">Port</th></tr></thead><tbody></tbody></table>
    <p class="ns-table-note">ในตัวอย่างนี้ P1, P2, P3 และ P8 เป็น Forwarding ส่วน P4–P7 ไม่มีลิงก์</p>
    <a href="#/chapter/1">อ่านบท Switching &amp; MAC →</a></div></div>`;
  scene.after(lab);
  const hud=main.querySelector('.quest-hud');if(hud)lab.after(hud);
  bind(scene.querySelector('.ns-jump'),'click',()=>lab.scrollIntoView({behavior:quiet()?'instant':'smooth',block:'start'}));
  const labButton=key=>lab.querySelector('[data-lab="'+key+'"]');
  const frames=[['A','B'],['B','A'],['A','B']];
  function mapGraphic(){
    const nodes=PORTS.filter(p=>p.active);
    const wires=nodes.map((p,i)=>{
      const x=70+i*140,cls=p.id===lastFrame?.input?'active-in':lastFrame?.outputs.includes(p.id)?'active-out':'';
      return '<path class="ns-wire '+cls+'" d="M270 55 Q270 80 '+x+' 101 L'+x+' 123"/>';
    }).join('');
    const labels=nodes.map((p,i)=>{
      const x=70+i*140;
      const col=p.id===lastFrame?.input?'#82bafa':lastFrame?.outputs.includes(p.id)?'#a9ebd1':'#8b969e';
      return '<g><rect x="'+(x-50)+'" y="119" width="100" height="42" rx="9" fill="#212529" stroke="'+col+'"/><text x="'+x+'" y="146" text-anchor="middle" fill="'+col+'" font-size="16">'+p.endpoint+'</text><text x="'+x+'" y="182" text-anchor="middle" fill="#c2c8cb" font-size="13">P'+p.id+' · '+(p.trunk?'Trunk':'VLAN '+p.vlans[0])+'</text></g>';
    }).join('');
    return '<svg class="ns-topology" viewBox="0 0 560 202" role="img" aria-label="SW1 ต่อ PC A พอร์ต 1 และ PC B พอร์ต 2 ใน VLAN 10 ต่อ PC C พอร์ต 3 ใน VLAN 20 และ SW2 ผ่าน trunk พอร์ต 8">'+wires+'<rect x="211" y="18" width="118" height="43" rx="10" fill="#33393d" stroke="#758187"/><text x="270" y="46" text-anchor="middle" fill="#fff" font-size="18">SW1</text>'+labels+'</svg>';
  }
  function stopPlay(){
    clearTimeout(timer);timer=0;playing=false;
    labButton('play').textContent='เล่นอัตโนมัติ';labButton('play').setAttribute('aria-pressed','false');
  }
  function paintLab(){
    lab.querySelector('.ns-map').innerHTML=mapGraphic();
    lab.querySelector('.ns-stage-count').textContent=seq?'เฟรม '+seq+' / 3':'ก่อนส่งเฟรม';
    const descriptions=[
      'เริ่มจากตาราง MAC ว่าง สวิตช์ยังไม่มีรายการของ A และ B',
      'A เข้า P1 → เรียนรู้ MAC ของ A ที่ P1 ยังไม่รู้ตำแหน่ง B จึง Flood ออก P2 และ P8 ใน VLAN 10',
      'B ตอบเข้า P2 → เรียนรู้ MAC ของ B ที่ P2 และพบ A ในตาราง จึงส่งออก P1 เพียงพอร์ตเดียว',
      'A ส่งหา B อีกครั้ง → พบ B อยู่ P2 แล้ว จึงส่งออกเฉพาะ P2 ส่วนลิงก์ Trunk ไม่ต้องรับเฟรมนี้'
    ];
    lab.querySelector('.ns-lab-status').textContent=descriptions[seq];
    const tbody=lab.querySelector('tbody');tbody.replaceChildren();
    if(!Object.keys(mac).length){const row=tbody.insertRow();const cell=row.insertCell();cell.colSpan=3;cell.textContent='ยังไม่มีรายการ';}
    else for(const [key,p] of Object.entries(mac)){
      const [vlan,address]=key.split('/'),row=tbody.insertRow();
      if(lastFrame?.input===p)row.className='ns-flash-row';
      for(const value of [address,vlan,'P'+p])row.insertCell().textContent=value;
    }
    labButton('step').textContent=['ส่ง A → B','ให้ B ตอบกลับ','ส่ง A → B อีกครั้ง','ส่งใหม่ตั้งแต่ต้น'][seq];
    if(lastFrame)pose.lights=[lastFrame.input,...lastFrame.outputs].slice(0,3);
    else pose.lights=[selectedPort];
    schedule();
  }
  function nextFrame(){
    if(seq===3){seq=0;mac={};lastFrame=null;}
    const [from,to]=frames[seq];lastFrame=transmit(mac,from,to);mac=lastFrame.table;seq++;paintLab();
  }
  function autoplay(){
    if(!playing||closed)return;
    nextFrame();if(seq===3){stopPlay();return;}timer=setTimeout(autoplay,2600);
  }
  bind(labButton('step'),'click',()=>{stopPlay();nextFrame();});
  bind(labButton('reset'),'click',()=>{stopPlay();seq=0;mac={};lastFrame=null;paintLab();});
  bind(labButton('play'),'click',()=>{
    if(playing){stopPlay();return;}
    playing=true;labButton('play').textContent='หยุด';labButton('play').setAttribute('aria-pressed','true');autoplay();
  });
  paintLab();
  let scrollFrame=0;
  function scrollPose(){
    scrollFrame=0;
    if(!scene.isConnected)return;
    const bounds=scene.getBoundingClientRect();
    const progress=quiet()?0:limit(-bounds.top/Math.max(1,bounds.height),0,1);
    scene.style.setProperty('--ns-lift',Math.round(progress*18)+'px');
    scene.style.setProperty('--ns-scale',String(1+progress*.045));
  }
  bind(window,'scroll',()=>{if(!scrollFrame&&visible)scrollFrame=requestAnimationFrame(scrollPose);},{passive:true});
  const reveal='IntersectionObserver' in window?new IntersectionObserver(entries=>{
    for(const entry of entries){
      if(!entry.isIntersecting)continue;
      reveal.unobserve(entry.target);
      if(!quiet()&&entry.target.animate)entry.target.animate([{opacity:.5,transform:'translateY(16px)'},{opacity:1,transform:'translateY(0)'}],{duration:520,easing:'cubic-bezier(.2,.72,.2,1)'});
    }
  },{threshold:.08}):null;
  reveal?.observe(lab.querySelector('.ns-experiment'));reveal?.observe(lab.querySelector('.ns-table-panel'));
  const resize='ResizeObserver' in window?new ResizeObserver(schedule):null;
  resize?.observe(canvas);
  if(!resize)bind(window,'resize',schedule);
  const visibility='IntersectionObserver' in window?new IntersectionObserver(entries=>{
    visible=!!entries[0]?.isIntersecting;if(visible)schedule();
  },{rootMargin:'100px'}):null;
  visibility?.observe(canvas);
  bind(document,'visibilitychange',()=>{if(document.hidden){stopPlay();last=0;}else schedule();});
  const motionObserver=new MutationObserver(()=>{if(quiet())stopSpin();});
  motionObserver.observe(document.documentElement,{attributes:true,attributeFilter:['data-motion']});
  const cleanup=()=>{
    if(closed)return;
    closed=true;life.abort();stopPlay();cancelAnimationFrame(raf);cancelAnimationFrame(scrollFrame);reveal?.disconnect();
    resize?.disconnect();visibility?.disconnect();motionObserver.disconnect();routeObserver.disconnect();
    renderer?.dispose();renderer=null;document.body.classList.remove('ns-home');
    if(current===cleanup)current=null;
  };
  const routeObserver=new MutationObserver(()=>{if(!scene.isConnected)cleanup();});
  routeObserver.observe(main,{childList:true});current=cleanup;
}
function watchOverview(){
  const main=document.getElementById('main');
  if(!main)return;
  let ticket=0;
  function mountAvailable(){
    ticket=0;
    const hero=main.querySelector('.hero');
    const layout=main.querySelector('.quest-layout')||main.querySelector('.chapter-grid');
    if(hero&&layout)install({main,hero,layout});
  }
  const observer=new MutationObserver(()=>{
    if(!ticket&&main.querySelector('.hero'))ticket=requestAnimationFrame(mountAvailable);
  });
  observer.observe(main,{childList:true});
  ticket=requestAnimationFrame(mountAvailable);
}
if(document.readyState!=='complete')document.addEventListener('DOMContentLoaded',watchOverview,{once:true});
else watchOverview();

})();
